package api

import (
	"context"

	"github.com/gin-gonic/gin"
	"github.com/go-redis/redis/v8"
	"go.mongodb.org/mongo-driver/mongo"

	"gitlab.com/piccolo_su/vegeta/pkg/harbor"

	"github.com/go-chi/chi"
	httpSwagger "github.com/swaggo/http-swagger"

	"gitlab.com/piccolo_su/vegeta/cmd/scanner/component"

	// _ "gitlab.com/piccolo_su/vegeta/cmd/scanner/docs" // docs is generated by Swag CLI
	// _ "gitlab.com/piccolo_su/vegeta/cmd/scanner/docs" // docs is generated by Swag CLI
	"gitlab.com/piccolo_su/vegeta/pkg/logging"
	"gitlab.com/piccolo_su/vegeta/pkg/response"
)

var (
	log *logging.Logger
)

func init() {
	log = logging.GetLogger()
}

// SetupRoutes is to set up the chi router
func SetupRoutes(
	ctx context.Context,
	r *chi.Mux,
	redclair *component.RedClairService,

	mongodb *mongo.Database,
	harborClient *harbor.HarborRESTClient,
	redisClient *redis.Client,

	virusScan *component.VirusScan,
	scannerDB *component.ScannerDB,

) {
	log.Debug().Msg("setting up routes...")

	r.Get("/ping", response.Pong)
	r.Get("/swagger/*", httpSwagger.Handler(httpSwagger.URL("swagger/doc.json")))

	api := newAPI(ctx, redclair, mongodb, harborClient, redisClient, virusScan, scannerDB)
	//r.Route("/harbor/api/v1", api.harbor())
	r.Route("/api", func(r chi.Router) {
		r.Route("/v1", func(r chi.Router) {
			r.Route("/scan", api.scan())
		})
	})
}

func SetupGinRouter(srv component.ScannerSrv) *gin.Engine {
	router := gin.Default()

	apiSrv := NewScannerSrv(srv)
	router.Use(gin.Logger(), gin.Recovery())

	v1 := router.Group("/api/v1/scan")
	{
		v1.GET("/reportsByImageList", apiSrv.ListScannedByImageList)         // 链条完成 first
		v1.GET("/reportsByImageOverview", apiSrv.ListScannedByImageOverview) // 链条完成 first
		v1.GET("/reportsByImageDetails", apiSrv.ScannedByImageDetails)       // 链条完成 first

		v1.POST("/scanone", apiSrv.StartScanOne)
		v1.POST("/harbor/scanAllNow", apiSrv.ScanAllNow)
		v1.GET("/harbor/scanStatus", apiSrv.GetScanStatus)
		v1.GET("/harbor/scanOneStatus", apiSrv.GetScanOneStatus)
		v1.GET("/reportsByVulnOverview", apiSrv.ListScannedByVulnOverview)
		v1.GET("/reportsBySimpleImageDetails", apiSrv.GetSimpleImageDetail)
	}

	v2 := router.Group("/api/v1/images")
	{
		v2.GET("/:imgDigest/layers", apiSrv.ListImgLayers)
	}

	v3 := router.Group("/api/v1/layers")
	{
		v3.GET("/:layerDigest/info", apiSrv.ImgLayerInfo)
	}

	v4 := router.Group("/api/v1/vulns")
	{
		v4.GET("/detail/:name", apiSrv.ScannedByVulnDetails)
		v4.GET("/statistic", apiSrv.ListScannedByVulnOverview)
		v4.GET("/all", apiSrv.ListScannedByVulnList)
		v4.GET("/relation", apiSrv.ListVulnRelation)
	}
	return router
}
